typeSystemExample.source:
function max<T extends number | string>(a: T, b: T): T {
  return a >= b ? a : b;
}

console.log(max(3, 7));
console.log(max(1.5, 2.8));

concurrencyExample.source:
async function square(n: number): Promise<number> {
  return n * n;
}

const results = await Promise.all(
  [0, 1, 2, 3].map(square)
);
console.log(...results);
